import sys

def extostr(cls, e, max_level=30, max_path_level=5):
    tb = traceback.TracebackException(sys.exc_info()[0], None, sys.exc_info()[2])
    lines = []
    for filename, lineno, funcname, line in traceback.format_exception(tb):
        if lineno != 1 and line.strip() != 'raise':
            lines.append('    ' * (max_path_level - 1))
