    if output is not None and not isinstance(output, list):
        raise ValueError("Argument 'output' must be a list")

    expanded_declarations = []
    for declaration in sequence:
        if isinstance(declaration, Interface):
            expanded_declarations.append(declaration)
        elif isinstance(declaration, tuple) and len(declaration) == 2:
            impl, interface = declaration
            if isinstance(impl, pycyphal.Interface) and isinstance(interface, pycyphal.Interface):
                expanded_declarations.append((impl, interface))
