def formatmany(sql, many_params):
    # Check if the parameters are valid
    if not isinstance(sql, (str, bytes)):
        raise TypeError("SQL must be a string or bytes object")
    if not isinstance(many_params, Iterable):
        raise TypeError("Many params must be an iterable object")

    # Convert the SQL query to use the out-style parameters
    formatted_sql = None
    many_params_list = []
    for params in many_params:
        if isinstance(params, Mapping):
            formatted_sql, params_dict = _format_dict_params(sql, params)
            many_params_list.append(params_dict)
        elif isinstance(params, Sequence):
            formatted_sql, params_tuple = _format_seq_params(sql, params)
            many_params_list.append(params_tuple)
        else:
            raise ValueError("Params must be a mapping or a sequence")

    return formatted_sql, many_params_list

