    private static function groupFilesByXMLFileName(/*source, xmls, files*/)
    {
        /* validate input */
        if(!(source && xmls && files))
        {
            throw new ArgumentException("Source, XML file names, and files are all required.");
        }

        for(let xml of xmls)
        {
            if(!(xml && xml.length))
            {
                throw new ArgumentException("Invalid XML file name.");
            }
        }

        for(let file of files)
        {
            if(!(file && file.length))
            {
                throw new ArgumentException("Invalid file.");
            }
        }

        /* implementation */
        let nodeMap = new HashMap();
        for(let node of xmls)
        {
            /* get fileName from file path */
            let fileName = node.split("/").pop();
            /* remove extension */
            let fileNameNoExt = fileName.substring(0, fileName.lastIndexOf("."));
            /* key is fileNameNoExt and value is node */
            nodeMap.set(fileNameNoExt, node);
        }

        let groups = new HashMap();
        for(let file of files)
        {
            /* get fileName from file path */
            let fileName = file.split("/").pop();
            /* get fileNameNoExt */
            let fileNameNoExt = fileName.substring(0, fileName.lastIndexOf("."));
            /* check if fileNameNoExt exists in nodeMap */
            if (nodeMap.has(fileNameNoExt))
            {
                /* get node from nodeMap */
                let node = nodeMap.get(fileNameNoExt);
                /* check if nodeGroup exists in groups */
                if (!groups.has(node))
                {
                    /* create nodeGroup */
                    groups.set(node, []);
                }
                /* add file to nodeGroup */
                groups.get(node).push(file);
            }
        }

        let result = new HashMap();
        for(let [key, value] of groups)
        {
            result.set(key, value);
        }

        return result;
    }
}

