    """Decorator for registering a VCS handler method."""

    if not isinstance(vcs, str) or not isinstance(method, callable):
        raise TypeError("VCS and method must be strings and callables, respectively.")

    vcs_map = {
        "git": method,
        "hg": method,
        "svn": method
    }

    if vcs not in vcs_map:
        raise ValueError(f"Invalid VCS: {vcs}")

    return vcs_map[vcs]

def vcs_handler(vcs, method):
    try:
        # call the decorated method and get the return value
        return_value = method(vcs)
    except Exception as e:
        # handle runtime errors
        print(f"RUNTIME ERROR: {e}")
        return None
    else:
        # success
        return return_value

