    major, minor, patch = version.split('.')
    patch = int(patch) + 1
    if patch == 10:
        minor = str(int(minor) + 1).zfill(2)
        patch = '0'
    if minor == '100':
        major = str(int(major) + 1).zfill(2)
        minor = '00'
        patch = '0'
    return '.'.join([major, minor, patch])

