def validate_version_inventories(self, version_dirs):
    """
    Validate the inventories of each version, ensuring that each version has an inventory up to that point.

    Also, keep a record of any content digests different from those in the root inventory so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in version sequence (1, 2, 3...).
    """

    root_inventory = self.get_root_inventory()
    root_digests = [d['digests'] for d in root_inventory.get_digests()]
    version_inventories = []
    version_digests = []

    # Iterate over the version directories and validate their inventories
    for version_dir in version_dirs:
        version_inventory = self.get_version_inventory(version_dir)
        version_digests.append(version_inventory.get_digests())

        # Check if each version's inventory is up to date
        for item in version_inventory.get_items():
            if 'digests' not in item:
                continue

            digests = item['digests']
            if digests is None:
                continue

            if digests.get(self.get_content_type()) != root_digests.get(self.get_content_type()):
                raise ValidationError(f'Invalid inventory for version {version_dir}: content digests do not match the root inventory')

    # Check for any differences between the version inventories and the root inventory
    for version, digests in enumerate(version_digests):
        for content_type, root_digest in root_digests.items():
            if content_type not in digests:
                continue
            if digests[content_type] != root_digest:
                raise ValidationError(f'Invalid inventory for version {version + 1}: content digest for {content_type} does not match the root inventory')

    return version_inventories

