        # one or both of the values are not MappingNodes, so we cannot deep merge them
        return node_value2

    result = {}

    # iterate over the keys in node_value1, only including those that do not exist in node_value2
    for key, _ in node_value1.value:
        if key not in node_value2.value:
            result[key] = deep_merge_node_values(node_value1.value[key], {})

    # iterate over the keys in node_value2, updating values in result if necessary
    for key, value in node_value2.value:
        if key in result:
            result[key] = deep_merge_node_values(result[key], value)
        else:
            result[key] = deep_merge_node_values({}, value)

