def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    import argparse

    arg_parser = argparse.ArgumentParser()
    subparsers = arg_parser.add_subparsers()

    global_args = []
    for arg in unparsed_arguments:
        if arg.startswith("-"):
            global_args.append(arg)
        else:
            break

    args_dict = {}

    for subparser_name in unparsed_arguments[len(global_args):]:
        if subparser_name == "global":
            continue

        subparser = subparsers.add_parser(subparser_name)
        args_dict[subparser_name] = subparser.parse_args(global_args + unparsed_arguments[len(global_args):])

    return args_dict

def parse_subparser_arguments(unparsed_arguments, subparsers):
    named_args = {}
    remaining_args = []

    for arg in unparsed_arguments:
        for name, parser in subparsers.items():
            try:
                namespace = parser.parse_known_args([arg])[0]
            except SystemExit:
                # If a subparser is unable to parse the argument, we move on to the next one.
                continue

            named_args[name] = namespace
            break
        else:
            # If an argument is not claimed by any subparser, it is included in the list of
            # remaining args.
            remaining_args.append(arg)

    return named_args, remaining_args

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_arguments = {}
    remaining_arguments = []

    for argument in unparsed_arguments:
        for subparser_name, subparser in subparsers.items():
            if argument in subparser.prefix_chars or argument.startswith('--'):
                try:
                    parsed_arguments[subparser_name] = subparser.parse_args(argument)
                except SystemExit:
                    # An exception is raised when an invalid argument is passed to
                    # subparser.parse_args. Since this method returns a tuple of
                    # (a dict mapping from subparser name to a parsed namespace of
                    # arguments, a list of remaining arguments not claimed by any
                    # subparser), we catch the exception and continue to the next
                    # argument.
                    pass
            else:
                # This argument is not claimed by any subparser. We add it to the list
                # of remaining arguments and continue to the next argument.
                remaining_arguments.append(argument)
                break
    return parsed_arguments, remaining_arguments

