    if not 0 <= number < 256:
        raise ValueError(f"Number {number} must be between 0 and 255")

    result = ""
    while number > 0:
        result = alphabet[number % 16] + result
        number //= 16

    if padding is not None:
        result = result.rjust(padding, "0")

    return result

