    if roots is None:
        roots = set()
    # Find all nodes in the graph that have no parents (i.e. are roots)
    for node in graph.nodes():
        if not graph.has_edge(node, prop, None):
            roots.add(node)
    # Recursively find all children of each root
    for root in roots:
        for node in graph.neighbors(root, prop):
            if node not in roots:
                roots.add(node)
                find_roots(graph, prop, roots)
    return roots

