def find_tags(text, replacer=None):
    tags = set()
    last_tag_index = 0
    in_code_block = False
    for i, c in enumerate(text):
        if c == '#' and not in_code_block:
            last_tag_index = i
            in_code_block = True
        elif c == '\n' and in_code_block:
            in_code_block = False
        elif in_code_block and c == '`':
            in_code_block = False
    if in_code_block:
        return  tags,  text
    new_text = text[:last_tag_index] + text[last_tag_index:].replace('#', '', 1)
    if not replacer:
        tags = {text[i:j] for i, j in ((m.start(0), m.end(0)) for m in re.finditer(r'#\w+', new_text))}
    else:
        tags = {replacer(text[i:j]) for i, j in ((m.start(0), m.end(0)) for m in re.finditer(r'#\w+', new_text))}
    return tags, new_text

