        alias = None
        if _type == 'Domain':
            alias = root.find('./{http://docs.oasis-open.org/ns/xri/xrd-1.0}Alias').text
        elif _type == 'ThirdParty':
            alias = root.find('./{http://docs.oasis-open.org/ns/xri/xrd-1.0}Endpoint').text
    else:
        # Parse as JSON (new)
        data = json.loads(document)
        if 'data' in data and 'attributes' in data['data'] and 'type' in data['data']['attributes']:
            _type = data['data']['attributes']['type']
            if _type == ' ThirdParty':
                alias = data['data']['attributes']['alias']
    return {'type': _type, 'alias': alias}

