def dict_insert(dic, val, key, *keys):
    # Check if the key already exists in the dictionary
    if key in dic:
        # If the key already exists, get the value of the key
        value = dic[key]
        # If the value is not a dictionary, raise an error
        if not isinstance(value, dict):
            raise ValueError("Invalid key: key {} already exists and is not a dictionary".format(key))
        # If the value is a dictionary, recursively call the function with the remaining keys
        return dict_insert(value, val, *keys)
    # If the key does not exist, create a new dictionary with the key and value
    dic[key] = val
    # If there are more keys to insert, recurse with the remaining keys
    if keys:
        return dict_insert(dic[key], *keys)
    # If there are no more keys to insert, return the dictionary
    return dic

def dict_insert(dic, val, key, *keys):
    """Insert a value of a nested key into a dictionary."""
    # Check if the input is valid
    if not isinstance(dic, dict):
        raise ValueError("Input dictionary is not valid")
    if not isinstance(val, (str, int, float)):
        raise ValueError("Input value is not valid")
    if not isinstance(key, str):
        raise ValueError("Input key is not valid")
    if not keys:
        raise ValueError("Input key chain is not valid")

    # Get the key chain as a list
    key_chain = [key] + list(keys)

    # Traverse the dictionary and insert the value
    current_dict = dic
    for k in key_chain:
        if k not in current_dict:
            current_dict[k] = {}
        current_dict = current_dict[k]
    current_dict["value"] = val

    return dic

