    with open(yaml_file, "r") as file:
        config = yaml.safe_load(file)

    # Validate that all fields are specified
    if not config.get("data"):
        raise IRValidatorException("'data' field is missing or empty")
    if not config.get("format"):
        raise IRValidatorException("'format' field is missing or empty")
    if not config.get("model_type"):
        raise IRValidatorException("'model_type' field is missing or empty")

    # Validate that the right fields are specified for each section
    for section in config["sections"]:
        if section["name"] != "model":
            raise IRValidatorException(f"Invalid section name: {section['name']}")

        if section["fields"] != ["field1", "field2", "field3"]:
            raise IRValidatorException(
                "Invalid fields specified for section 'model'. Expected: ['field1', 'field2', 'field3']"
            )

        # Validate that the field values are valid
        for field in section["fields"]:
            if field not in ["field1", "field2", "field3"]:
                raise IRValidatorException(
                    f"Invalid field value '{field}' specified for section 'model'"
                )

    # Validate that the validators are applied correctly
    if not config["validators"].get("CustomValidator1"):
        raise IRValidatorException(
            "Validator 'CustomValidator1' is not applied to the 'data' field"
        )
    if not config["validators"].get("CustomValidator2"):
        raise IRValidatorException(
            "Validator 'CustomValidator2' is not applied to the 'format' field"
        )
    if not config["validators"].get("CustomValidator3"):
        raise IRValidatorException(
            "Validator 'CustomValidator3' is not applied to the 'model_type' field"
        )

    return config

