class SpecFileParser(object):
    def _include_groups(self, parser_dict):
        include_groups = parser_dict.get('include_groups', None)
        if include_groups is None or len(include_groups) == 0:
            return
        group_specs = []
        base_dir = os.path.dirname(self.input_file)
        for group in include_groups.values():
            group_specs.extend(self._load_group_specs(group, base_dir))
        self.specs.extends(group_specs)

    def _load_group_specs(self, group, base_dir):
        group_dir = os.path.join(base_dir, group)
        if not os.path.exists(group_dir):
            return []
        group_specs = []
        for f in os.listdir(group_dir):
            spec_file = os.path.join(group_dir, f)
            if not os.path.isfile(spec_file):
                continue
            if f.endswith('.yaml') or f.endswith('.yml'):
                group_specs.extend(yaml.safe_load(open(spec_file)))
            elif f.endswith('.json'):
                group_specs.extend(json.load(open(spec_file)))
            else:
                pass
        return group_specs

