    """Resolves the include dict directive in the spec files.

    :param parser_dict: A dictionary of parser elements.
    :type parser_dict: dict
    :returns: A dictionary of parsed elements.
    :rtype: dict
    """
    parsed_elements = {}

    for key, value in parser_dict.items():
        if key.startswith("include"):
            include_path = key.split(":")[1].strip()
            with open(include_path, "r") as f:
                include_data = yaml.safe_load(f.read())
            parsed_elements = {**parsed_elements, **include_data}

    return parsed_elements

