    :param command_name: The name of the command (e.g. "main", "virsh", "ospd", etc.)
    :return: A list of options for the specified command
    """

    command_options = []

    if command_name in self.parser.commands:
        command_group = self.parser.commands[command_name]
        for option_group in command_group.option_groups:
            for option in option_group.options:
                command_options.append(option)

    return command_options

