def _get_conditionally_required_args(self, command_name, options_spec, args):
    required_args = []
    for option in options_spec:
        if 'required_when' in option:
            requirement = option['required_when']
            if requirement.startswith('{} == '):
                requirement_arg = requirement[7:-2]
                if requirement_arg in args:
                    required_args.append(option['name'])
            elif requirement.startswith('not {} == '):
                requirement_arg = requirement[8:-2]
                if requirement_arg not in args:
                    required_args.append(option['name'])
            elif requirement == 'any':
                for arg in args:
                    required_args.append(option['name'])
                    break
            elif requirement == 'none':
                if not any(arg in args for arg in args):
                    required_args.append(option['name'])
            else:
                raise ValueError(f'Unsupported required_when condition: {requirement}')
    return required_args

