    # Get environment variables
    env = os.environ.copy()
    env["IR_WORKSPACE"] = os.path.abspath(ir_workspace.path)
    env["IR_PLUGIN"] = os.path.abspath(ir_plugin.path)

    # Build argument list
    ansible_script = os.path.join(ir_plugin.path, "ansible", "ansible-playbook")
