def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    # Step 1: Validate input parameters
    if not isinstance(ir_workspace, InfraredWorkspace):
        raise ValueError("Expected an InfraredWorkspace object as the first argument")
    if not isinstance(ir_plugin, InfraredPlugin):
        raise ValueError("Expected an InfraredPlugin object as the second argument")
    if not isinstance(playbook_path, str) or not os.path.isfile(playbook_path):
        raise ValueError("Expected a string file path to a valid Ansible playbook as the third argument")
    if verbose is not None and not isinstance(verbose, int):
        raise ValueError("Expected an integer value for the verbosity level")
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise ValueError("Expected a dictionary object for the extra variables")
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise ValueError("Expected a dictionary object for the Ansible arguments")

    # Step 2: Set up Ansible
    ansible_path = os.path.join(ir_plugin.ansible_root, "ansible-playbook")
    ansible_ctl = subprocess.Popen([ansible_path, "-i", playbook_path], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)

    # Step 3: Pass input parameters to Ansible
    ansible_ctl.stdin.write(json.dumps(ansible_args).encode())
    ansible_ctl.stdin.write(b"--extra-vars json=\"")
    ansible_ctl.stdin.write(json.dumps(extra_vars).encode())
    ansible_ctl.stdin.write(b"\";\r\n")

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
