def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to the main entry point.

    :param subparser: the subparser object to extend.
    """
    # Step 1: Create the spec subparser
    spec_parser = root_subparsers.add_parser(
        "spec", help="Generate the spec from the current model"
    )

    # Step 2: Define the subcommands for the spec subparser
    spec_parser.add_subparsers(
        help="The spec subcommands", dest="spec_subcommand"
    )

    # Step 3: Define the options for the spec subcommand "from-model"
    from_model_parser = spec_parser.add_subparser(
        "from-model", help="Generate the spec from the current model"
    )

    # Step 4: Define the options for the spec subcommand "from-input"
    from_input_parser = spec_parser.add_subparser(
        "from-input", help="Generate the spec from a YAML file"
    )

    # Step 5: Define the options for the spec subcommand "from-dir"
    from_dir_parser = spec_parser.add_subparser(
        "from-dir", help="Generate the spec from a directory of YAML files"
    )

    # Step 6: Handle invalid inputs and runtime issues
    try:
        # Make sure the subcommand is valid
        if not spec_parser.subcommand:
            raise ValueError("Spec subcommand is not valid")

        # Run the corresponding subcommand
        if spec_parser.subcommand == "from-model":
            run_from_model(from_model_parser)
        elif spec_parser.subcommand == "from-input":
            run_from_input(from_input_parser)
        elif spec_parser.subcommand == "from-dir":
            run_from_dir(from_dir_parser)
        else:
            raise ValueError("Spec subcommand is not valid")
    except (ValueError, RuntimeError) as e:
        print(e)

def extend_cli(self, root_subparsers):
    for parser in root_subparsers.choices.values():
        parser.add_argument('-s', '--spec', action='store_true', help='Whether to print the spec or not')

        parser.add_argument('-v', '--verbosity', type=int, default=0, help='The level of verbosity (0: quiet, 1: default, 2: verbose)')

        parser.add_argument('-o', '--output', type=str, help='The file to write the spec to')

        parser.set_defaults(func=self.run_speccli)

